use std::fs

fn main() {
    let n = 200000
    let mut comp: Vec<bool> = []
    let mut cnt: Vec<int> = []
    let mut last: Vec<int> = []
    let mut i = 0
    while i <= n {
        comp.push(false)
        cnt.push(0)
        last.push(0)
        i += 1
    }
    i = 2
    while i <= n {
        if !comp[i] {
            let mut j = i * i
            while j <= n {
                comp[j] = true
                j += i
            }
        }
        i += 1
    }
    let mut c = 0
    let mut l = 0
    i = 0
    while i <= n {
        if i >= 2 && !comp[i] {
            c += 1
            l = i
        }
        cnt[i] = c
        last[i] = l
        i += 1
    }
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut first = true
    for line in text.lines() {
        if first {
            first = false
            continue
        }
        let t = line.trim()
        if t.len() == 0 {
            continue
        }
        let q: int = t.parse().unwrap_or(0)
        if last[q] == 0 {
            println("0 none")
        } else {
            println("${cnt[q]} ${last[q]}")
        }
    }
}

